package com.lamggm.rospocket;
import android.content.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class FreeGridBoardTest {
 DashboardBoard board()throws Exception{android.app.Activity activity=Robolectric.buildActivity(android.app.Activity.class).setup().visible().get();Context c=activity;DashboardBoard b=new DashboardBoard(c);b.bind(DashboardLayout.decode(FreeGridLayoutTest.positioned().toString()),null);for(String id:DashboardLayout.IDS)b.addCard(id,id,new MetricCard(c),null);activity.setContentView(b);SquareCardTest.measure(b,1200);return b;}
 static DragEvent event(int action,float x,float y,Object local)throws Exception{for(java.lang.reflect.Method m:DragEvent.class.getDeclaredMethods()){Class<?>[] p=m.getParameterTypes();if(!m.getName().equals("obtain")||p.length<4||p[0]!=int.class)continue;Object[] args=new Object[p.length];int f=0;for(int i=0;i<p.length;i++)args[i]=p[i]==int.class?action:p[i]==float.class?(f++==0?x:f==2?y:0f):p[i]==boolean.class?false:p[i]==Object.class?local:null;m.setAccessible(true);return (DragEvent)m.invoke(null,args);}throw new AssertionError("No framework drag factory");}
 static Object token(DashboardBoard b,String id)throws Exception{java.lang.reflect.Field owner=DashboardBoard.class.getDeclaredField("editOwner");owner.setAccessible(true);Class<?> type=Class.forName("com.lamggm.rospocket.DashboardBoard$Drag");java.lang.reflect.Constructor<?> make=type.getDeclaredConstructor(Object.class,String.class);make.setAccessible(true);return make.newInstance(owner.get(b),id);}
 @Test public void dropAnywhereOnFreeGridPersistsButOccupiedAndRevokedDropsDoNot()throws Exception{DashboardBoard b=board();b.edit();SquareCardTest.measure(b,1200);View grid=b.findViewWithTag("dashboard-grid");Object data=token(b,"watch0");assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,0,0,data)));assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DROP,6*132,3*132,data)));assertEquals(6,b.layout().get("watch0").column);assertEquals(3,b.layout().get("watch0").row);assertTrue(b.save());assertEquals(3,new DashboardStore(b.getContext().getFilesDir()).load().get("watch0").row);b.edit();SquareCardTest.measure(b,1200);data=token(b,"watch0");String before=b.layout().encode();assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,0,0,data)));assertFalse(grid.dispatchDragEvent(event(DragEvent.ACTION_DROP,2*132,0,data)));assertEquals(before,b.layout().encode());Object stale=token(b,"watch0");assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,0,0,stale)));b.cancel();b.edit();String next=b.layout().encode();assertFalse(grid.dispatchDragEvent(event(DragEvent.ACTION_DROP,0,0,stale)));assertEquals(next,b.layout().encode());}
 @Test public void freeGridPreservesEmptyCellsRatherThanPackingCardsIntoRows()throws Exception{DashboardBoard b=board();View a=b.findViewWithTag("dashboard-card:watch0"),second=b.findViewWithTag("dashboard-card:watch1"),robot=b.findViewWithTag("dashboard-card:robot");int gap=Math.round(12*b.getResources().getDisplayMetrics().density);assertEquals("Saved empty cell must remain empty",2*(a.getWidth()+gap),second.getLeft());assertEquals(4*(a.getHeight()+gap),robot.getTop());b.edit();SquareCardTest.measure(b,1200);assertEquals("Editing must retain square cell content",a.getWidth(),a.getHeight());assertTrue(b.findViewWithTag("dashboard-overlay:watch0").isLongClickable());}
 @Test public void unconfirmedSaveThenRejectedDropKeepsTheUncertaintyWarning()throws Exception{DashboardBoard b=board();DashboardStore fault=new DashboardStore(b.getContext().getFilesDir()){@Override void verify(DashboardLayout expected)throws java.io.IOException{throw new java.io.IOException("injected readback failure");}};java.lang.reflect.Field field=DashboardBoard.class.getDeclaredField("store");field.setAccessible(true);field.set(b,fault);b.edit();SquareCardTest.measure(b,1200);assertFalse(b.save());android.widget.TextView notice=b.findViewWithTag("dashboard-persistence-status");assertTrue(notice.getText().toString().contains("incerto"));View grid=b.findViewWithTag("dashboard-grid");Object data=token(b,"watch0");assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,0,0,data)));assertFalse(grid.dispatchDragEvent(event(DragEvent.ACTION_DROP,2*132,0,data)));String warning=notice.getText().toString();assertTrue(warning,warning.contains("incerto")&&warning.contains("Cancelar descarta"));b.cancel();assertEquals(View.VISIBLE,notice.getVisibility());}
 @Test public void nonzeroGrabAnchorSnapsTheCardOriginInsteadOfTheFinger()throws Exception{DashboardBoard b=board();b.edit();SquareCardTest.measure(b,1200);java.lang.reflect.Field owner=DashboardBoard.class.getDeclaredField("editOwner");owner.setAccessible(true);Class<?> type=Class.forName("com.lamggm.rospocket.DashboardBoard$Drag");java.lang.reflect.Constructor<?> make=type.getDeclaredConstructor(Object.class,String.class,float.class,float.class);make.setAccessible(true);Object data=make.newInstance(owner.get(b),"watch0",90f,90f);View grid=b.findViewWithTag("dashboard-grid");assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,0,0,data)));assertTrue(grid.dispatchDragEvent(event(DragEvent.ACTION_DROP,6*132+90,3*132+90,data)));assertEquals(6,b.layout().get("watch0").column);assertEquals(3,b.layout().get("watch0").row);}
}
